import pytest


def age_at(born: int, now: int) -> int:
    """Whole years between birth year `born` and the current year `now`.

    Only years are given, so the result is `now - born`. The current year is
    a parameter and the clock is never read.

    Raises ValueError if `now` is earlier than `born`.
    """
    if now < born:
        raise ValueError("now is earlier than born")
    return now - born


def test_age_basic() -> None:
    assert age_at(1990, 2024) == 34


def test_age_same_year_is_zero() -> None:
    assert age_at(2000, 2000) == 0


def test_age_one_year() -> None:
    assert age_at(1999, 2000) == 1


def test_age_long_span() -> None:
    assert age_at(1900, 2024) == 124


def test_age_before_birth_raises() -> None:
    with pytest.raises(ValueError):
        age_at(2025, 2024)


def test_age_returns_int() -> None:
    assert isinstance(age_at(1980, 2020), int)
